sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({api, event, helpers, imports}) {

    if (api.context.props.isDeleteModal == "true") {
        // Update states and open modal
        if (api.data.validate_delete_action_1.output) {
            var output = api.data.validate_delete_action_1.output;
            api.setState("canProceedDeletion", output.canRemove);
            api.setState("deleteErrorMessage", output.errorMessage);
        }

        if(event.elementId == 'delete_button' && event.name == 'NOW_BUTTON#CLICKED'){
            // TODO: There is a bug in UIB page, modal is not working as expected. 
            // Alternate approach: Delete without confirmation
        }
    }

}
